package net.kourlas.dashtone.service.data.local

import androidx.room.Entity
import androidx.room.ForeignKey
import androidx.room.Index
import androidx.room.PrimaryKey

/**
 * The primary key mirrors the stable MediaStore audio row id (MediaStore.Audio.Media._ID)
 * rather than being separately autogenerated, since MediaStore ids are already stable natural
 * keys and reusing them avoids an extra id-lookup indirection during scanning.
 */
@Entity(
    tableName = "songs",
    foreignKeys = [
        ForeignKey(
            entity = AlbumEntity::class,
            parentColumns = ["id"],
            childColumns = ["albumId"],
            onDelete = ForeignKey.CASCADE,
        ),
        ForeignKey(
            entity = ArtistEntity::class,
            parentColumns = ["id"],
            childColumns = ["artistId"],
            onDelete = ForeignKey.CASCADE,
        ),
    ],
    indices = [Index("albumId"), Index("artistId")],
)
data class SongEntity(
    @PrimaryKey val id: Long,
    val title: String,
    val trackNumber: Int,
    val discNumber: Int,
    val durationMs: Long,
    val albumId: Long,
    val artistId: Long,
    val contentUri: String,
    val dateAdded: Long,
    val dateModified: Long,
    /** Denormalized rather than a separate Genre entity+DAO like Album/Artist: the browse tree
     * groups by this raw string directly (see [net.kourlas.dashtone.service.shuffle.Grouping.GENRE]
     * and [net.kourlas.dashtone.service.playback.LibraryBrowseTree]'s GENRES_ROOT), so the extra
     * join infrastructure a real entity+DAO would need isn't earning its keep. Null if MediaStore
     * doesn't report a genre for this song (also true on API < 30, where GENRE isn't a directly
     * queryable column). */
    val genreName: String? = null,
    /** Same rationale as [genreName]; MediaStore.Audio.Media.ALBUM_ARTIST, distinct from the
     * (track) artist -- relevant for compilation albums with a consistent "Various Artists"-style
     * album artist but per-track artists that vary. */
    val albumArtistName: String? = null,
    /** Same rationale as [genreName]; MediaStore.Audio.Media.COMPOSER. */
    val composerName: String? = null,
    /** Full folder path relative to the containing volume's public root (e.g. "Music/ABBA/Gold"),
     * backing the Folders browse category -- see
     * [net.kourlas.dashtone.service.data.mediastore.fullFolderPathOf]. Null on API < 29, where
     * MediaStore has no RELATIVE_PATH column (same gating as [genreName] on API < 30). */
    val folderPath: String? = null,
    /** MediaStore's VOLUME_NAME for the volume that holds this song (see
     * [net.kourlas.dashtone.service.data.mediastore.RawAudioRow.volumeName]). A scan reads it to
     * keep songs on a volume that is not mounted -- see
     * [net.kourlas.dashtone.service.data.mediastore.MediaStoreLibraryScanner]. Null on API < 29. */
    val volumeName: String? = null,
)

/** The two columns a scan reads to decide whether a song that it did not find can be deleted. */
data class SongIdAndVolume(val id: Long, val volumeName: String?)
